EXPECTED_HASHES = {'app.py': '3629df2ba431fa34b4c0cc7a9f98232edad37ed3d67033cea20080ece1b29a97', 'services/v13_blueprints.py': 'c1279e284eccf35fe2d51f043535d3b45bb43a424961088c6c407528cca88135', 'templates/prospect_concept.html': 'ee5043a40bd3f4b9aad3e90f5466cbf0bfbb26ad6b4b7bf6ec0c6d881ed68b19', 'templates/prospect_concept_preview.html': '2ba6b54668d24d41c83f783d278a4ba035a9a96b0ebad995f86b19d9440afb7f', 'static/v13.css': 'dcd82da69115f16ad256d9ceb4d1ad9c2d12883941245de51acb7f9e362dd03c', 'scripts/test_v13_foundation.py': '791ebb25808ac97eb8ad322a517a7fc93b59cc06d98a7d60e60aca6886242b40'}
PAYLOAD = {'services/v13_blueprints.py': '', 'services/v13_creative_director.py': '', 'services/v13_site_model.py': '', 'templates/prospect_concept.html': '', 'templates/prospect_concept_preview.html': '', 'static/v13.css': '', 'scripts/test_v13_foundation.py': '', 'scripts/test_v13_creative_director.py': '', 'ARCHITECTURE_V13_CREATIVE_DIRECTOR.md': ''}
OLD_IMPORT = 'from services.v13_blueprints import generate_blueprint\n'
NEW_IMPORT = 'from services.v13_creative_director import generate_concept_blueprint\nfrom services.v13_site_model import build_site_model\n'
OLD_GENERATE = '    try:\n        blueprint = generate_blueprint(dict(business), creative_brief, concept_number)\n        concept = create_concept(conn, bid, creative_brief, blueprint, "LOCAL_DESIGNER")\n        flash(\n            f"Private concept {concept[\'concept_number\']} generated. Nothing was published.",\n            "success",\n        )\n'
NEW_GENERATE = '    try:\n        director = generate_concept_blueprint(dict(business), creative_brief, concept_number)\n        concept = create_concept(\n            conn,\n            bid,\n            creative_brief,\n            director.blueprint,\n            director.generation_mode,\n        )\n        flash(\n            f"Private concept {concept[\'concept_number\']} generated. Nothing was published.",\n            "success",\n        )\n'
