def sha256(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()

def git_output(*args):
    try:
        return subprocess.check_output(["git", *args], cwd=ROOT, text=True, stderr=subprocess.STDOUT).strip()
    except Exception as exc:
        return f"unavailable: {exc}"

def replace_once(text, old, new, label):
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f"{label}: expected exactly one anchor, found {count}")
    return text.replace(old, new, 1)

def main():
    print("Business OS v13 - Creative Director Consolidated Installer")
    print(f"Repository: {ROOT}")
    if ROOT.name != EXPECTED_ROOT:
        raise SystemExit(f"ABORT: expected repository folder named {EXPECTED_ROOT}, got {ROOT.name}")
    print("\nCurrent branch:")
    print(git_output("branch", "--show-current"))
    print("Current working-tree changes (informational; installer will not commit):")
    print(git_output("status", "--short") or "clean")
    print("\nVerifying exact inspected source snapshot...")
    for rel, expected in EXPECTED_HASHES.items():
        path = ROOT / rel
        if not path.exists():
            raise SystemExit(f"ABORT: required file missing: {rel}")
        actual = sha256(path)
        if actual != expected:
            raise SystemExit(f"ABORT: {rel} changed since inspection.\nExpected {expected}\nActual   {actual}\nNothing changed. Send a fresh source snapshot before retrying.")
        print(f"  OK {rel}")
    for rel in ("services/v13_creative_director.py", "services/v13_site_model.py", "scripts/test_v13_creative_director.py"):
        if (ROOT / rel).exists():
            raise SystemExit(f"ABORT: {rel} already exists. Nothing changed; inspect current repo before rerunning.")
    app_path = ROOT / "app.py"
    app_text = app_path.read_text(encoding="utf-8")
    app_new = replace_once(app_text, OLD_IMPORT, NEW_IMPORT, "v13 imports")
    app_new = replace_once(app_new, OLD_GENERATE, NEW_GENERATE, "concept generation route")
    app_new = replace_once(app_new, OLD_PREVIEW, NEW_PREVIEW, "concept preview route")
    stamp = datetime.now().strftime("%Y%m%d-%H%M%S")
    backup = ROOT / ".v13_backups" / f"creative-director-{stamp}"
    backup.mkdir(parents=True, exist_ok=False)
    for rel in EXPECTED_HASHES:
        source = ROOT / rel
        target = backup / rel
        target.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(source, target)
    print(f"\nBackup created: {backup}")
    for rel, encoded in PAYLOAD.items():
        path = ROOT / rel
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(base64.b64decode(encoded))
    app_path.write_text(app_new, encoding="utf-8", newline="\n")
    print("\nPASS: blueprint schema v2 installed")
    print("PASS: context-aware Creative Director provider boundary installed")
    print("PASS: safe prospect render model installed")
    print("PASS: six materially different layout families installed")
    print("PASS: internal engineering disclaimers removed from prospect-facing page")
    print("PASS: compact prospect-to-demo operator workflow installed")
    print("PASS: live publishing/provider/SMS/scheduling gates were not modified")
    print("\nNext verification commands:")
    print("  python -m compileall app.py services scripts")
    print("  python scripts/test_v12_schema.py")
    print("  python scripts/test_v12_renderer.py")
    print("  python scripts/test_v13_foundation.py")
    print("  python scripts/test_v13_creative_director.py")
    print("  git diff --check")
    print("  git status --short")
    print("\nDo not commit/tag yet. Visual acceptance on multiple prospects comes next.")

if __name__ == "__main__":
    main()
